css:
@media screen {
    /* Frappe já dá ao .print-format uma "folha A4 flutuante" nativa
       (max-width/min-height/background/border-radius, ver
       templates/styles/standard.css) - só reforçamos com sombra, sem
       redeclarar width/padding/min-height e arriscar um valor
       ligeiramente diferente do nativo. */
    .print-format-preview {
        box-shadow: 0 2px 16px rgba(0, 0, 0, 0.18);
    }

    /* Simulação do rodapé: NÃO tentamos desenhar linhas de quebra de
       página a cada 297mm - a pré-visualização HTML é um scroll
       contínuo, sem o motor de paginação do wkhtmltopdf, e qualquer
       posição calculada aqui divergiria da quebra real do PDF (fontes,
       margens e o próprio layout engine são diferentes). Em vez disso,
       o rodapé fica fixo ("sticky") ao fundo da folha enquanto se faz
       scroll pelos artigos - o utilizador vê sempre o texto que se vai
       repetir por página, sem uma simulação de posição que poderia
       enganar mais do que ajudar. A paginação exata fica para o botão
       "PDF", que já reflete o resultado real (verificado com pypdf).
    */
    .print-format-preview #footer-html {
        position: sticky;
        bottom: 0;
        background: #fff;
        margin-top: 10mm;
        box-shadow: 0 -2px 6px rgba(0, 0, 0, 0.08);
    }

    .print-format-preview table thead tr th {
        background: #f5f5f5;
    }

    .print-format-preview table tbody tr {
        border-bottom: 1px solid #eee;
    }
}

@media print {
    /* Numeração de página para a rota de impressão nativa do browser
       (/printview?...trigger_print=1), que NUNCA passa pelo wkhtmltopdf -
       é a própria janela de impressão do Chrome/browser que gera o PDF,
       por isso as classes "page"/"topage" (convenção exclusiva do
       wkhtmltopdf, preenchidas pelo seu motor de --header-html/
       --footer-html) ficam sempre vazias aqui. CSS Paged Media (suportado
       no Chrome recente) resolve só a numeração, via contador nativo do
       browser - continua sem repetir o TEXTO do rodapé em cada página
       física, porque isso exigiria "running headers" (content: element(...))
       que o Chrome ainda não suporta de forma fiável. O botão "PDF"
       continua a ser o único caminho com rodapé E paginação garantidos. */
    @page {
        @bottom-right {
            content: "Página " counter(page) " de " counter(pages);
            font-family: Arial, sans-serif;
            font-size: 9px;
            color: #555;
        }
    }
}

html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{% if letter_head and not no_letterhead %}
		<div class="letter-head">{{ letter_head }}</div>
	{% endif %}
	{% if print_heading_template %}
		{{ frappe.render_template(print_heading_template, {"doc":doc}) }}
	{% endif %}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break invoice-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>
	{%- if doc.meta.is_submittable and doc.docstatus==2-%}
		<div class="text-center" document-status="cancelled">
			<h4 style="margin-top: 20px;">{{ _("CANCELLED") }}</h4>
		</div>
	{%- endif -%}
	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}
		<div class="text-center" document-status="draft">
			<h4 style="margin-top: 20px !important;">{{ _("DRAFT") }}</h4>
		</div>
	{%- endif -%}

	<style>
		.letter-head {
			margin-top: 12px !important;
		}
		.invoice-wrapper {
			font-family: "Inter", sans-serif;
			color: var(--black-overlay-700);
		}

		.print-format-body {
			padding: 30px 12px 12px 12px !important;
		}

		body {
			margin-bottom: 0mm !important;
			padding: 0px !important;
		}

		table.info-table,
		table.items-table,
		table.tax-table {
			border-collapse: separate;
			border-spacing: 0;
			border: 1px solid #ededed;
			border-radius: 10px;
			overflow: hidden;
		}

		table.info-table td {
			border-bottom: 1px solid #ededed;
			padding: 8px 10px !important;
		}
		table.items-table td,
		table.tax-table td {
			border-bottom: 1px solid #ededed;
			padding: 8px;
		}

		table.info-table td:not(:first-of-type),
		table.items-table td:not(:first-of-type),
		table.tax-table td:not(:first-of-type) {
			border-left: 1px solid #ededed;
		}

		table.info-table tbody tr:last-of-type td,
		table.items-table tbody tr:last-of-type td,
		table.tax-table tbody tr:last-of-type td {
			border-bottom: none;
		}

		thead.table-header {
			background: #f8f8f8;
		}
		thead.table-header td {
			color: #7c7c7c;
		}

		.text-center {
			text-align: center;
		}
		.text-left {
			text-align: left;
		}
		.text-right {
			text-align: right;
		}
		.text-muted {
			color: #7c7c7c;
		}
		.text-dark {
			color: #525252;
		}
		.text-bold {
			font-weight: bold;
		}
		.small-text {
			color: #666;
		}

		.mt-10 {
			margin-top: 10px;
		}
		.mt-15 {
			margin-top: 15px;
		}
		.mt-20 {
			margin-top: 20px;
		}
		.mt-40 {
			margin-top: 40px;
		}
		.mt-80 {
			margin-top: 80px;
		}
		.mb-20 {
			margin-bottom: 20px;
		}
		.pb-8 {
			padding-bottom: 8px;
		}
		.amount-width {
			width: 110px;
		}

		.totals-table {
			border-radius: 5px;
			width: 100%;
		}
		.totals-table td {
			padding: 4px 8px;
		}
		.totals-table tr {
			border-bottom: 1px solid #ededed;
			position: relative;
		}
		.totals-table tr td {
			position: relative;
		}
		.totals-table tr td div {
			width: 12%;
			height: 14px;
			background-color: white;
			position: absolute;
			bottom: -6px;
			left: 0%;
			color: white;
		}
		.totals-table tr:last-child {
			border-bottom: none;
		}
		.totals-table .grand-total td {
			padding: 6px 8px;
			font-weight: bold;
		}

		.words-box {
			background: #f8f8f8;
			border-radius: 8px;
			padding: 8px;
			line-height: 21px;
			letter-spacing: 0.21px;
			font-size: small;
		}

		.info-card {
			color: #7c7c7c;
		}

		.title {
			color: #7c7c7c !important;
		}

		.heading {
			color: #525252 !important;
			font-weight: 300;
		}

		.print-format {
			color: #171717;
			font-size: 14px;
			font-style: normal;
			font-weight: 420;
			line-height: 21px;
			padding: 0px;
			letter-spacing: 0.14px;
			margin-left: 0mm !important;
			margin-right: 0mm !important;
		}
		.letter-head-footer {
			margin-top: 0px !important;
		}
		.print-heading {
			margin-top: 0px !important;
			margin-bottom: 0px !important;
			padding-bottom: 0px !important;
		}

		/* ===== Injeção Compliance PT ===== */
		.pt-legal-footer {
			font-size: 9px;
			color: #555;
			border-top: 1px solid #333;
			padding-top: 4px;
			padding-left: 8mm;
			padding-right: 8mm;
			margin-top: 6px;
		}
		.pt-exemption-legend {
			font-size: 9px;
			color: #555;
			margin-top: 6px;
		}
	</style>
	<div class="print-format-body">
		{% set company_doc = frappe.get_doc("Company", doc.company) %}
		{% set exemption_notes = namespace(codes=[]) %}
		<table style="width: 100%;" class="mb-20">
			<tr>
				<td style="vertical-align: top; width: 78%;">
					<table class="info-table" style="width: 100%">
						<tr>
							<td style="width: 50%">
								<span class="heading">{{ _("Customer Name") }}:</span> {{doc.customer_name }}
							</td>
							<td style="width: 50%">
								<span class="heading">{{ _("Payment Due Date") }}:</span> {{
								frappe.utils.format_date(doc.due_date) }}
							</td>
						</tr>
						<tr>
							<td>
								<span class="heading">{{ _("Invoice Number") }}:</span> {{ doc.name }}
								&nbsp;&nbsp;<span class="heading">ATCUD:</span> {{ get_atcud_code(doc) or "-" }}
							</td>
							<td>
								<span class="heading">{{ _("Invoice Date") }}:</span> {{
								frappe.utils.format_date(doc.posting_date) }}
							</td>
						</tr>
						<tr>
							<td><span class="heading">{{ _("Bill From") }}:</span><br />
								{% if doc.company_address %}
			                        {% set company_address = frappe.db.get_value("Address", doc.company_address, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
			                        {{  doc.company }}<br>
			                        {{ company_address.get("address_line1") or "" }}<br>
			                        {% if company_address.get("address_line2") %}{{ company_address.get("address_line2") }}<br>{% endif %}
			                        {{ company_address.get("city") or "" }}, {{ company_address.get("state") or "" }} {{ company_address.get("pincode") or "" }}, {{ company_address.get("country") or "" }}<br>
			                    {% endif %}
								<span class="heading">{{ _("Contribuinte") }}:</span> {{ get_company_nif(doc.company) }}
							</td>
							<td><span class="heading">{{ _("Bill To") }}:</span><br />
							    {% if doc.customer_address %}
									{% set customer_address = frappe.db.get_value("Address", doc.customer_address, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
			                        {{ doc.customer_name }}<br>
									{{ customer_address.address_line1 or "" }}<br>
									{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}
									{{ customer_address.city or "" }} {{ customer_address.state or "" }} {{ customer_address.pincode or "" }} {{ customer_address.country or "" }}<br>
								{% endif %}
								<span class="heading">{{ _("Contribuinte") }}:</span> {{ doc.tax_id or _("Consumidor final") }}
							</td>
						</tr>
					</table>
				</td>
				<td style="vertical-align: top; width: 22%; text-align: right; padding-left: 10px;">
					{% set qr_data = get_qr_code_data(doc=doc) %}
					{% if qr_data %}
					<img src="{{ generate_qr_code_image(qr_data, 280) }}" style="width: 28mm; height: 28mm;">
					{% endif %}
				</td>
			</tr>
		</table>

		<!-- Items Table -->
		{% set item_naming_by = frappe.db.get_single_value("Stock Settings", "item_naming_by") %}
		<table class="items-table mt-15" style="width: 100%">
			<thead class="table-header">
				<tr>
					<td class="text-center">{{ _("No") }}</td>
					<td class="text-left">{{ _("Item") }}</td>
					{% if item_naming_by != "Item Code" %}
						<td class="text-left">{{ _("Item Code") }}</td>
					{% endif %}
					<td class="text-right">{{ _("Quantity") }}</td>
					<td class="text-right">{{ _("Rate") }}</td>
					<td class="text-right">{{ _("Amount") }}</td>
				</tr>
			</thead>
			<tbody>
				{% for item in doc.items %}
				<tr>
					<td class="text-center text-dark">{{ loop.index }}</td>
					<td>{{ item.item_name }}{{ register_exemption_note(item, exemption_notes) | safe }}</td>
					{% if item_naming_by != "Item Code" %}
						<td class="text-left">{{ item.item_code }}</td>
					{% endif %}
					<td class="text-right text-dark">{{ item.get_formatted("qty", 0) }} {{ item.uom }}</td>
					<td class="text-right text-dark">{{ item.get_formatted("net_rate", doc) }}</td>
					<td class="text-right" style="color: #171717">
						{{ item.get_formatted("net_amount", doc) }}
					</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>

		<!-- Totals Section -->
		<table style="width:100%; margin-top: 15px">
			<td style="vertical-align: bottom !important; width: 60%;">
				<p class="title">{{ _("Total in words") }}</p>
				<div class="words-box text-uppercase">{{ doc.in_words }}</div>
			</td>
			<td>
				&nbsp;
			</td>
			<td style="width: 38%;">
				<table class="totals-table">
					<tr>
						<td class="text-right text-muted"><div></div>{{ _("Sub Total:") }}</td>
						<td class="text-right amount-width">{{ doc.get_formatted("total", doc) }}</td>
					</tr>
					{%- if doc.apply_discount_on == "Net Total" -%}
						<tr>
							<td class="text-right text-muted">
								<div></div>{{ _("Discount") }} ({{ doc.additional_discount_percentage }}%):
							</td>
							<td class="text-right amount-width">{{ doc.get_formatted("discount_amount", doc) }}</td>
						</tr>
					{%- endif -%}
					{%- for tax in doc.taxes -%}
						{%- if (tax.tax_amount or print_settings.print_taxes_with_zero_amount) and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}
							<tr>
								<td class="text-right text-muted"><div></div>{{ tax.get_formatted("description") }} ({{ tax.get_formatted("rate") }}%):</td>
								<td class="text-right amount-width">{{ tax.get_formatted("tax_amount") }}</td>
							</tr>
						{%- endif -%}
					{%- endfor -%}
					{%- if doc.apply_discount_on == "Grand Total" -%}
						<tr>
							<td class="text-right text-muted">
								<div></div>{{ _("Discount") }} ({{ doc.additional_discount_percentage }}%):
							</td>
							<td class="text-right amount-width">{{ doc.get_formatted("discount_amount", doc) }}</td>
						</tr>
					{%- endif -%}
					<tr class="grand-total">
						<td class="text-right">{{ _("Grand Total:") }}</td>
						<td class="text-right amount-width">{{ doc.get_formatted("grand_total", doc) }}</td>
					</tr>
				</table>
			</td>
		</table>

		{% if exemption_notes.codes %}
		<div class="pt-exemption-legend">
			{{ render_exemption_legend(exemption_notes, style="") | safe }}
		</div>
		{% endif %}

		<!-- Terms -->
		<div class="terms-section">
			{% if doc.terms %}
			<div class="info-card mt-40">
				<div>{{ _("Terms and Conditions") }}</div>
				{{ doc.terms}}
			</div>
			{% endif %}
	</div>
	<div id="footer-html" class="visible-pdf">
		{% if not no_letterhead and footer %}
		<div class="letter-head-footer">
			{{ footer }}
		</div>
		{% endif %}
		<div class="pt-legal-footer">
			{% set sig = get_signature_hash_control(doc) %}
			<span style="color: #000 !important;">{{ sig or "" }}-Processado por programa certificado n.º {{ frappe.db.get_single_value("Portugal Auth Settings", "software_certificate_number") or "0" }}/AT{% if frappe.db.get_single_value("Portugal Auth Settings", "sandbox_mode") %} — AMBIENTE DE TESTES, sem valor fiscal{% endif %}.</span><br>
			<span style="color: #555 !important;">{{ get_compliance_version_notice() }}</span>
		</div>
		<p class="text-center small page-number visible-pdf">
			{{ _("Page {0} of {1}").format('<span class="page"></span>', '<span class="topage"></span>') }}
		</p>
	</div>
</div>
{% endfor %}
